"""Current continuous-WER figures and context-guided response ratings."""
import copy,json,re,hashlib
from html import escape as e
from pathlib import Path
from s1_array_audio_view import render as audio_browser,case_button
from s1_acoustic_revision_view import render_measurements
from s1_revised_controls_view import render as pilot_controls
ROOT=Path(__file__).resolve().parents[1]
LABELS={'headset_mix':'Headset mix','distant_01':'One distant microphone','beamformed_mdm8':'Eight-microphone beamformed audio'}
DIMENSIONS={'relevance':'Question relevance','support':'Factual support','adequacy':'Answer adequacy'}
AVAILABILITY={'none':'No earlier file-status evidence','partial':'Some file-status evidence','full':'Full question-status reference evidence'}
def read(p):return json.loads(p.read_text())
def rating(v):return 'N/A' if v is None else str(v)+' / 5'
def render(t):
 d=read(ROOT/'research/s1-context-judge/review.json');old=read(ROOT/'research/s1-revised-sweep/review.json');rubric=read(ROOT/'research/s1-context-judge/rubric.json');protocol=read(ROOT/'research/s1-context-judge/protocol.json');quality={c['id']:c for c in d['cases']};inputs={c['id']:c for c in protocol['cases']};data=copy.deepcopy(old)
 for c in data['cases']:
  if c['id'] in quality:c['quality']=quality[c['id']]['quality']
 valid=sum(c['quality']['valid'] for c in d['cases']);resources=d['resources']
 body='<style>#response-quality-heatmap,#array-response-content,#context-elbow-analysis,#ami-array-sweep,#judge-method,[id^="array-wer-"]{scroll-margin-top:10rem}.quality-feedback{overflow-wrap:anywhere}</style><header class="hero"><h1>Experiment progress</h1><p>Automatic speech recognition (ASR) produces a transcript. Word error rate (WER) measures transcription errors. Response content is now evaluated separately using the question, available context and source-based reference.</p></header>'
 body+='<section class="section" id="summary"><ul class="brief"><li>Figures 1–3 show continuous question WER, with the Figure 1 headset curve reused as the baseline in Figures 2 and 3.</li><li>A new local LLM evaluation covers '+str(valid)+'/120 completed spoken responses across three dimensions; three generation failures remain unscored.</li><li>Every response retains its audio, independent ASR transcript, judge feedback and available context.</li><li>The 105-question full benchmark still awaits reference and evaluator validation.</li></ul><p><a href="#array-audio-demos">Audio demos</a> · <a href="#array-response-browser">Response ASR and ratings</a> · <a href="#array-wer-headset_mix">Figures 1–3: question WER</a> · <a href="#array-response-content">Figure 4: response quality</a> · <a href="#context-elbow-analysis">Analysis</a></p><p>Evaluation snapshot: '+e(d['reviewed_utc'])+'. This update rejudges the saved acoustic rerun; it does not generate new S1 speech.</p></section>'
 body+='<section class="section" id="revised-question-audio"><h2>Question audio</h2><p>The acoustic revision covers all 105 primary questions and six published voice alternatives. Original question text, insertion timing and source audio before and after each insertion are preserved. <a href="experiments/question-audio.html">Listen to all revised questions and remaining ASR caveats</a>.</p></section>'
 body+='<section class="section" id="ami-array-sweep"><h2>Question recognition across preceding-audio lengths</h2><p>Figures 1–3 compare S1’s recognized question text with the known spoken question. They measure input-question recognition; Figure 4 instead evaluates what S1 says in its response. One TS3006c question follows zero to 309.03 seconds of earlier audio. Each microphone uses its own acoustically matched question. The headset mix, one raw distant channel (Array1-01), and released mono eight-microphone beamformed signal (MDM8) use the same selected histories and 480 ms input packets. Raw and beamformed source gains remain +16.52 dB and −6.00 dB, respectively. Histories are untrimmed, S2 is disabled, and the caller enables a response at the known question end. The replay is unpaced and does not measure conversational latency.</p><p>These are selected AMI question-bank meetings rather than an official named ASR split. This sweep uses the TS3006c scenario meeting; the earlier pilot additionally uses non-scenario EN2004a. The model receives mono signals. Released MDM8 beamforming is offline and may use later-recording statistics. <a href="research/s1-array-sweep/recording-provenance.json">Recording provenance</a>.</p>'
 wer_rows=[]
 for name,label in LABELS.items():
  rows=[r for r in old['cases'] if r['condition']==name];values=[r['recognition']['WER'] for r in rows if r['WER_valid']];wer_rows.append([e(label),str(len(values))+'/41',format(sum(values)/len(values),'.3f'),str(41-len(values))])
 body+=t('One question at 41 context positions per microphone; means include scored WER windows only and are descriptive, without confidence intervals.',['Recording signal','Scored WER windows','Mean question WER','Unscored generation failures'],wer_rows)
 body+=audio_browser(data)
 for n,(name,label) in enumerate(LABELS.items(),1):
  body+='<figure id="array-wer-'+name+'"><div style="overflow-x:auto" tabindex="0"><img src="research/s1-context-judge/asr-'+name+'.svg" alt="'+e(label)+' continuous question WER across preceding-audio lengths" style="width:100%;min-width:850px;background:white"></div><figcaption>Figure '+str(n)+'. '+e(label)+' question WER. WER counts substitutions, deletions and insertions divided by the reference word count; lower is better, and repetitions can make it exceed 1. Each point is a different earlier-audio length for this same question. '+('This headset curve is the baseline used in Figures 2 and 3.' if n==1 else 'The dashed Headset baseline is exactly the Figure 1 curve at the same lengths.')+' Failed recognition windows are gaps. Values use the unchanged S1 question-ASR window from the packet overlapping the source cutoff through four post-question packets. No pass/fail cutoff or keyword criterion is applied in these plots. <a href="research/s1-context-judge/asr-'+name+'.svg">SVG</a> · <a href="research/s1-context-judge/asr-'+name+'.png">PNG</a>.</figcaption></figure>'
 body+='<details id="earlier-ASR-rule"><summary>What did the previous “WER cutoff” and “strict ASR criterion” mean?</summary><p>The earlier diagnostic called a question recognized only when WER was at most 0.25 and the transcript also contained Assistant, shared, folder, conceptual and design. That extra keyword rule could reject an otherwise near-correct transcript because the wake word was missing. It was a diagnostic choice, not a standard definition of ASR quality. The current figures use continuous WER and omit that rule.</p></details></section>'
 body+='<section class="section" id="array-response-content"><h2>Figure 4: context-aware response quality</h2><p>The local Qwen3-30B-A3B-Instruct-2507 judge receives the actual question, the source transcript corresponding to each selected audio suffix, a source-based reference limited to the evidence in that suffix, and the independent Parakeet transcript of the generated response. The source transcript is evaluation evidence; it was not supplied to S1. Microphone labels, context-length labels, S1 question-ASR results and earlier scores are hidden from the judge.</p><p>Topical relevance receives only the question and response. The model selects a response category mapped to a fixed rubric anchor: an offer without an answer is 3, a partial status report is 4, and a direct answer or explicit inability to determine the status is 5. Each dimension uses a separate judge call; adequacy also receives the factual-support assessment to check its use of available evidence. Topical relevance is not penalized by design for factual errors. A separate clause-classification call distinguishes factual assertions from greetings, offers and comments about missing evidence. Only factual assertions are scored for support against available source statements and the question, without the full reference. N/A is assigned when there are no such assertions. The judge gives separate 1–5 ratings, with higher values better. <strong>Question relevance</strong> asks whether the response addresses the question. <strong>Factual support</strong> checks material assertions against the available source evidence, and is N/A when the response makes no factual assertion. Unsupported means not established by this context; it need not be false outside the meeting. <strong>Answer adequacy</strong> asks how usefully and completely the response answers the question given its available context. A bare offer is not a completed answer; an honest inability to determine the status can be appropriate when the relevant context is absent. There is no combined score.</p>'
 qrows=[]
 for s in d['summary']:
  qrows.append([LABELS[s['condition']]]+[('N/A' if s[k]['mean'] is None else format(s[k]['mean'],'.2f')+' / 5 ('+str(s[k]['n'])+' responses)') for k in DIMENSIONS]+[str(s['unsupported_claim_responses'])+'/'+str(s['valid'])])
 body+=t('Local LLM ratings on actual response ASR; ordinal means are descriptive. Support means omit N/A rather than treating it as zero or five. Unsupported-claim counts are judge findings, not human labels.',['Recording signal','Mean relevance','Mean factual support','Mean adequacy','Responses with unsupported/contradicted claims'],qrows)
 version=hashlib.sha256((ROOT/'research/s1-context-judge/response-quality.svg').read_bytes()).hexdigest()[:12]
 body+='<figure id="response-quality-heatmap"><div style="overflow-x:auto" tabindex="0"><img src="research/s1-context-judge/response-quality.svg?v='+version+'" alt="Three score heatmaps comparing headset, distant microphone and beamformed responses across all 41 ordered context lengths" style="width:100%;min-width:1000px;background:white"></div><figcaption>Figure 4. Local LLM ratings as heatmaps: separate rows for each microphone, with one column per tested history. Columns are ordered by increasing earlier-audio length and equally spaced; their widths do not represent elapsed time. Tick labels show actual minutes. Cell numbers are the unchanged 1–5 ratings. Grey dashes mean judge factual-support N/A; hatched crosses mean generation failed. The top strip marks available folder-status evidence, with full evidence from 193.17 seconds (3.22 minutes). The right column gives the mean / number of scored responses, excluding N/A and failures. One question; no smoothing, interpolation or uncertainty intervals. <a href="research/s1-context-judge/response-quality.svg?v='+version+'">SVG</a> · <a href="research/s1-context-judge/response-quality.png?v='+version+'">PNG</a> · <a href="research/s1-context-judge/scores.csv">Exact ratings CSV</a>.</figcaption></figure>'
 body+='<section id="context-elbow-analysis"><h3>What the scores suggest</h3>'+''.join('<p>'+e(s)+'</p>' for s in d['interpretation'])+'</section>'
 examples=[]
 for cid,note in [('headset_mix-L29','An offer to check permissions; no completed status answer.'),('distant_01-L35','Claims a completed check and says the folder is ready; no tool check was performed.'),('beamformed_mdm8-L22','Repeats the recent discussion of fresh colours and speech recognition, but does not answer the folder-status question.')]:
  r=next(r for r in data['cases'] if r['id']==cid);q=quality[cid]['quality'];examples.append([e(LABELS[r['condition']])+' · '+format(r['context_seconds'],'.2f')+' s',e(r['spoken_transcript']),'; '.join(DIMENSIONS[k]+': '+rating(q['scores'][k]) for k in DIMENSIONS),e(note)+' '+case_button(r)])
 body+=t('Three source-checked response patterns at their stated context lengths; the first two have full folder-status evidence, while the third repeats a later topic. Displayed ratings are the unchanged local-LLM outputs. Reviewer notes are Codex source comparisons, not human labels.',['Recording / earlier audio','Actual response ASR','Local judge ratings','Source comparison / playback'],examples)
 audit=read(ROOT/'research/s1-context-judge/content-audit.json')
 if audit['rating_flags']:
  flag_rows=[]
  for flag in audit['rating_flags']:
   r=next(r for r in data['cases'] if r['id']==flag['case_id']);flag_rows.append([e(LABELS[r['condition']])+' · '+format(r['context_seconds'],'.2f')+' s',DIMENSIONS[flag['dimension']]+': '+rating(quality[r['id']]['quality']['scores'][flag['dimension']]),e(flag['reason'])+' '+case_button(r)])
  body+='<details id="judge-source-flags"><summary>Source comparisons that disagree with judge ratings</summary>'+t('Codex source-comparison flags, not independent human labels. The figure retains every original local-model rating.',['Recording / earlier audio','Unchanged local judge rating','Source comparison / playback'],flag_rows)+'</details>'
 body+='<details id="judge-method"><summary>Judge prompt, reference design, qualification and papers</summary><p>References are scoped to the selected history: omitted facts are removed, and histories without the folder discussion receive an insufficient-context reference. Separate criterion prompts use explicit per-score anchors, a short evidence-based critique before each rating, and a source-based reference. It does not require exact reference wording, compulsory PowerPoint keywords, or unavailable facts. The full context also includes D’s later difficulty cutting and pasting into another folder; that does not prove an outage or a completed assistant lookup.</p><p>The design draws on <a href="https://aclanthology.org/2023.emnlp-main.153/">G-Eval</a> for explicit evaluation steps and separate aspects, <a href="https://arxiv.org/abs/2306.05685">MT-Bench’s LLM-as-a-judge study</a> for reference-guided grading and bias checks, and <a href="https://arxiv.org/abs/2405.01535">Prometheus 2</a> for criterion-specific 1–5 anchors and feedback. This is a Qwen prompting adaptation, not a reproduction of G-Eval probability weighting or a Prometheus model.</p><p>Qualification uses twelve authored synthetic responses plus an empty-answer guard, declared before actual-case scoring. They cover correct paraphrases, offers, greetings, contradiction, invented checks, unrelated biography, reference leakage into empty context, and appropriate abstention. Twelve actual responses are rejudged with the question, context, reference and response fields reordered in the adequacy prompt. The relevance and support prompts repeat unchanged as controls. These are development checks used during prompt refinement, not held-out accuracy tests or independent human validation. Passing output-structure and citation checks does not establish that every rating is correct.</p>'
 body+=t('Score anchors applied by the local judge; factual support is additionally N/A when there are no material factual claims.',['Dimension','1','2','3','4','5'],[[v['label']]+[e(v['anchors'][str(i)]) for i in range(1,6)] for k,v in rubric.items() if k in DIMENSIONS])
 body+='<p><a href="research/s1-context-judge/rubric.json">Exact rubric</a> · <a href="research/s1-context-judge/protocol.json">Every question, context and reference</a> · <a href="research/s1-context-judge/fixtures.json">Authored qualification cases</a> · <a href="research/s1-context-judge/judge-calls.json">Exact prompts and raw judgments</a> · <a href="research/s1-context-judge/review.json">Scores, qualification and prompt-order probes</a> · <a href="research/s1-context-judge/content-audit.json">Separate Codex source-comparison notes</a></p></details>'
 body+='<details id="array-sweep-examples"><summary>Every context, response, rating and source passage</summary>'
 for name,label in LABELS.items():
  rows=[r for r in data['cases'] if r['condition']==name];body+='<details><summary>'+e(label)+'</summary>'+t(label+' saved responses.',['Level / earlier audio','Question WER','Response'],[[str(r['index'])+' / '+format(r['context_seconds'],'.2f')+' s',format(r['recognition']['WER'],'.3f') if r['WER_valid'] else 'N/A',case_button(r)] for r in rows])
  for r in rows:
   body+='<details id="sweep-'+r['id']+'"><summary>Level '+str(r['index'])+' · '+format(r['context_seconds'],'.2f')+' s</summary><p><strong>Question ASR:</strong> '+e(r.get('question_asr') or '(empty)')+'</p>'
   if r['response_valid']:
    c=quality[r['id']];q=c['quality'];inp=inputs[r['id']];body+='<audio controls preload="none" src="'+e(r['audio'])+'" aria-label="'+e(label)+' level '+str(r['index'])+' response"></audio><p><strong>Actual response ASR:</strong> '+e(r['spoken_transcript'] or '(empty)')+'</p><p><strong>Local judge:</strong> '+e('; '.join(DIMENSIONS[k]+': '+rating(q['scores'][k]) for k in DIMENSIONS))+'</p><p>'+e(q['reference_comparison'])+'</p>'
    for k in DIMENSIONS:body+='<p><strong>'+DIMENSIONS[k]+':</strong> '+e(q['feedback'].get(k,''))+'</p>'
    for claim in q['claims']:body+='<p class="quality-feedback"><strong>'+e(claim['verdict'])+':</strong> '+e(claim['claim']+' '+claim['explanation']+' Source IDs: '+', '.join(claim['context_sentence_ids']))+'</p>'
    body+='<details><summary>Question, available source transcript and reference</summary><p><strong>Question:</strong> '+e(inp['question'])+'</p><p><strong>Reference guidance:</strong> '+e(inp['reference']['answer'])+'</p><p><strong>Evidence availability:</strong> '+e(AVAILABILITY[c['availability']])+'. This context-specific reference is evaluation guidance, not extra context supplied to S1. The full curator reference is retained in the protocol download.</p>'+''.join('<p><strong>'+e(s['id']+' · '+s['speaker'])+':</strong> '+e(s['text'])+'</p>' for s in inp['context'])+'</details><details><summary>Native intended speech text</summary><p>'+e(r['speech_text'] or '(empty)')+'</p></details>'
   else:body+='<p>Unscored generation: '+e(r.get('error') or r['status'])+'</p>'
   body+='</details>'
  body+='</details>'
 body+='</details><details id="legacy-fact-judge"><summary>Earlier two-fact scoring, preserved separately</summary><p>The earlier judge evaluated literal coverage of two facts only where five selected source passages were present. Its 0/33 complete-answer count and Codex source comparison remain in the original records, alongside the old figures. Those binary scores are not the new 1–5 quality ratings.</p><p><a href="research/s1-revised-sweep/review.json">Earlier two-fact records</a> · <a href="research/s1-revised-sweep/response-content.svg">Earlier fact-coverage figure</a></p></details></section>'
 body+=render_measurements().replace('ASR job ', 'Earlier input qualification, before this evaluation: ASR job ')
 body+='<details id="rerun-resources"><summary>Current judge resources and earlier rerun accounting</summary><p>Current judge job '+e(resources['job'])+' uses one '+e(resources['gpu_type_vram'])+'. Qwen3-30B weights and a 2 GiB key/value cache share logical GPU 0; no S1, TTS or ASR service shares the allocation. All source generation and ASR finish before judging; fixture qualification precedes real scoring. Maximum one GPU active for this update; now zero. Allocation '+str(resources['allocated_seconds'])+' seconds / '+format(resources['gpu_hours'],'.6f')+' GPU hours. '+str(resources['LLM_calls'])+' LLM calls; '+format(resources['judging_wall_seconds'],'.2f')+' seconds of judging, or '+format(resources['responses_per_judging_second'],'.3f')+' primary responses per judging second including qualification/probes.</p><p>Figure generation, paper review and publication use zero GPUs. The preceding acoustic rerun used 9.094444 GPU hours, with independent one-GPU jobs and maximum four active; its per-job types, roles, sharing and dependencies remain preserved below.</p>'
 body+='<p>Total for this judge update, including prior failed allocations: '+format(resources['total_GPU_hours'],'.6f')+' GPU hours.</p>'
 for attempt in resources.get('prior_attempts',[]):body+='<p>Earlier judge job '+e(attempt['job'])+': '+e(attempt['state'])+', one '+e(attempt['gpu_type_vram'])+', '+str(attempt['allocated_seconds'])+' seconds / '+format(attempt['gpu_hours'],'.6f')+' GPU hours. '+e(attempt['reason'])+'</p>'
 body+=t('Earlier acoustic-rerun parent allocations, preserved without new inference.',['Job / state','GPUs / type / VRAM','GPU role','GPU hours'],[[e(j['job']+' / '+j['state']),str(j['allocated_gpu_count'])+' / '+e(j['gpu_type_vram']),e(j['role']),format(j['gpu_hours'],'.6f')] for j in old['accounting']['jobs']])+'</details>'
 body+=pilot_controls(t)
 present=set(re.findall(r'\bid="([^"]+)"',body))|{'main','counts','checklist','software-checks','examples','reporting','appendix','retired-method','implementation','MathJax-script'}
 archive=ROOT/'study-progress-original-acoustics.html'
 if archive.exists():
  body+='<details id="earlier-experiment-links"><summary>Earlier experiments and original recordings</summary>'
  for key in dict.fromkeys(re.findall(r'\bid="([^"]+)"',archive.read_text())):
   if key not in present:body+='<p id="'+e(key)+'"><a href="study-progress-original-acoustics.html#'+e(key)+'">Earlier '+e(key.replace('-',' '))+'</a></p>'
  body+='</details>'
 return body
